/* BalVoice — authentication (Supabase Auth).
 *
 * Handles: Google sign-in, email + password sign-up/sign-in, phone sign-up/sign-in
 * with SMS codes (delivered by BMS through the send-sms Edge Function), password
 * reset, the OAuth/email-link callback, and the dashboard session guard.
 *
 * Configuration comes from assets/js/config.js (generated by build.py from .env).
 * If Supabase is not configured, auth pages explain this and the dashboard runs in
 * demo mode.
 *
 * Security notes
 * - PKCE flow for OAuth; email links use token_hash (works across devices).
 * - Redirect targets are restricted to local pages (no open redirects).
 * - Error messages never reveal whether an email or phone number has an account.
 * - Optional Cloudflare Turnstile protects sign-up, sign-in, and SMS requests.
 * - Real enforcement (rate limits, password policy, CAPTCHA, allowed countries)
 *   happens in Supabase and the Edge Function — see docs/AUTH-SUPABASE.md.
 */
(function () {
  "use strict";

  const cfg = window.BALVOICE_CONFIG || {};
  const configured = !!(cfg.supabaseUrl && cfg.supabaseAnonKey && window.supabase && window.supabase.createClient);
  const client = configured ? window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, {
    auth: { flowType: "pkce", persistSession: true, autoRefreshToken: true, detectSessionInUrl: true }
  }) : null;
  const siteUrl = (cfg.siteUrl && !/example\.com/.test(cfg.siteUrl)) ? cfg.siteUrl.replace(/\/$/, "") : location.origin + location.pathname.replace(/\/[^/]*$/, "");

  const COUNTRIES = {
    GH: { name: "Ghana", dial: "233", len: [9] },
    NG: { name: "Nigeria", dial: "234", len: [10] },
    KE: { name: "Kenya", dial: "254", len: [9] },
    CI: { name: "Côte d'Ivoire", dial: "225", len: [10] },
    TG: { name: "Togo", dial: "228", len: [8] },
    BF: { name: "Burkina Faso", dial: "226", len: [8] },
    GB: { name: "United Kingdom", dial: "44", len: [10] },
    US: { name: "United States", dial: "1", len: [10] }
  };
  const RESEND_SECONDS = 60;
  const MAX_CODE_ATTEMPTS = 5;

  const $ = (sel, root) => (root || document).querySelector(sel);
  const $$ = (sel, root) => Array.prototype.slice.call((root || document).querySelectorAll(sel));
  const params = new URLSearchParams(location.search);
  const hashParams = new URLSearchParams(location.hash.replace(/^#/, ""));

  /* Redirects ------------------------------------------------------------- */
  // Only allow local pages such as "dashboard.html" or "dashboard.html#/groups".
  function safeNext(raw) {
    const v = String(raw || "");
    return /^[a-z0-9-]+\.html(#\/[a-z0-9/?=&_-]*)?$/i.test(v) ? v : "dashboard.html";
  }
  const nextPage = safeNext(params.get("next"));
  const callbackUrl = () => siteUrl + "/auth-callback.html?next=" + encodeURIComponent(nextPage);
  function goNext() { location.replace(nextPage); }

  /* UI helpers ------------------------------------------------------------ */
  function alertBox(kind, html) {
    const el = $("#auth-alert");
    if (!el) return;
    if (!html) { el.hidden = true; el.innerHTML = ""; return; }
    el.className = "auth-alert is-" + kind;
    el.innerHTML = html;
    el.hidden = false;
    el.setAttribute("tabindex", "-1");
    el.focus({ preventScroll: false });
  }
  const esc = s => String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  function fieldError(input, msg) {
    const field = input.closest(".field");
    if (field) {
      field.classList.toggle("has-error", !!msg);
      const e = field.querySelector(".field-error");
      if (e) e.textContent = msg || "";
    }
    input.setAttribute("aria-invalid", String(!!msg));
    return !msg;
  }
  function termsError(form, msg) {
    const e = $(".terms-error", form);
    if (e) { e.textContent = msg || ""; e.style.display = msg ? "block" : "none"; }
    return !msg;
  }
  function busy(btn, on, label) {
    if (!btn) return;
    if (on) { btn.dataset.label = btn.textContent; btn.textContent = label || "Please wait…"; btn.disabled = true; btn.setAttribute("aria-busy", "true"); }
    else { btn.textContent = btn.dataset.label || btn.textContent; btn.disabled = false; btn.removeAttribute("aria-busy"); }
  }
  const validEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v) && v.length <= 160;

  // Friendly, non-revealing error messages.
  function friendly(err) {
    const code = (err && (err.code || err.error_code)) || "";
    const msg = String((err && err.message) || "").toLowerCase();
    const status = err && err.status;
    if (code === "invalid_credentials" || /invalid login credentials/.test(msg)) return "The email or password is incorrect.";
    if (code === "email_not_confirmed" || /email not confirmed/.test(msg)) return "Please confirm your email address first. Check your inbox for the link we sent.";
    // Supabase uses otp_expired for both wrong and expired codes.
    if (code === "otp_expired" || /expired/.test(msg)) return "That code or link is incorrect or has expired. Check it and try again, or request a new one.";
    if (code === "otp_disabled" || code === "signup_disabled" || /signups not allowed/.test(msg)) return "We couldn't sign you in. BalVoice accounts are created by an administrator — ask them for an invitation.";
    if (/token has expired or is invalid|invalid otp|otp.*invalid/.test(msg)) return "That code is incorrect or has expired.";
    if (code === "weak_password" || /password should/.test(msg)) return "Please choose a stronger password: " + esc(err.message);
    if (code === "captcha_failed" || /captcha/.test(msg)) return "Please complete the security check and try again.";
    if (code === "sms_send_failed" || /sms/.test(msg) && /fail|error/.test(msg)) return "We couldn't send a text message right now. Please try again in a few minutes.";
    if (status === 429 || /rate limit|too many/.test(msg)) return "Too many attempts. Please wait a few minutes and try again.";
    if (code === "same_password") return "Your new password must be different from your current one.";
    if (code === "phone_provider_disabled" || /unsupported phone provider/.test(msg)) return "Phone sign-in is not available at the moment. Please use email or Google.";
    if (/failed to fetch|network/.test(msg)) return "We couldn't reach the server. Check your connection and try again.";
    return "Something went wrong. Please try again.";
  }

  /* Password rules (mirror the Supabase password policy) ------------------ */
  function pwChecks(v) {
    return { length: v.length >= 10, mix: /[a-z]/.test(v) && /[A-Z]/.test(v), digit: /\d/.test(v) };
  }
  function bindPasswordMeter(input) {
    const meter = $("[data-pw-meter]", input.closest(".field"));
    const rules = $$("[data-rule]", input.closest(".field"));
    const update = () => {
      const c = pwChecks(input.value);
      let score = Object.values(c).filter(Boolean).length + (input.value.length >= 14 ? 1 : 0);
      rules.forEach(li => li.classList.toggle("is-met", !!c[li.dataset.rule]));
      if (meter) { meter.style.width = (score / 4) * 100 + "%"; meter.dataset.score = String(score); }
    };
    input.addEventListener("input", update);
    update();
  }
  function passwordProblem(v) {
    const c = pwChecks(v);
    if (!c.length) return "Use at least 10 characters.";
    if (!c.mix) return "Include both upper and lower case letters.";
    if (!c.digit) return "Include at least one number.";
    return "";
  }

  /* Phone ----------------------------------------------------------------- */
  function allowedCountries() {
    const list = (cfg.allowedPhoneCountries && cfg.allowedPhoneCountries.length ? cfg.allowedPhoneCountries : ["GH"]).filter(c => COUNTRIES[c]);
    return list.length ? list : ["GH"];
  }
  function fillCountries(select) {
    select.innerHTML = allowedCountries().map(c => `<option value="${c}">${esc(COUNTRIES[c].name)} (+${COUNTRIES[c].dial})</option>`).join("");
    if (select.options.length === 1) select.classList.add("is-single");
  }
  // Returns E.164 ("+233241234567") or null.
  function toE164(country, raw) {
    const c = COUNTRIES[country];
    if (!c) return null;
    let d = String(raw || "").replace(/[^\d+]/g, "");
    if (d.startsWith("+")) { d = d.slice(1); if (!d.startsWith(c.dial)) return null; d = d.slice(c.dial.length); }
    else if (d.startsWith("00" + c.dial)) d = d.slice(2 + c.dial.length);
    else if (d.startsWith(c.dial) && d.length > Math.max.apply(null, c.len)) d = d.slice(c.dial.length);
    if (d.startsWith("0")) d = d.slice(1);
    return c.len.indexOf(d.length) > -1 ? "+" + c.dial + d : null;
  }
  const maskPhone = p => p.slice(0, 4) + " ••• ••" + p.slice(-3);

  /* CAPTCHA (Cloudflare Turnstile, optional) ------------------------------ */
  const captcha = { enabled: !!cfg.turnstileSiteKey, tokens: new Map(), widgets: new Map(), loading: null };
  function loadTurnstile() {
    if (!captcha.enabled) return Promise.resolve(false);
    if (captcha.loading) return captcha.loading;
    captcha.loading = new Promise(resolve => {
      const s = document.createElement("script");
      s.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
      s.async = true; s.onload = () => resolve(true); s.onerror = () => resolve(false);
      document.head.appendChild(s);
    });
    return captcha.loading;
  }
  function renderCaptchas(root) {
    $$("[data-captcha]", root).forEach(el => {
      if (!captcha.enabled) { el.hidden = true; return; }
      loadTurnstile().then(ok => {
        if (!ok || !window.turnstile || captcha.widgets.has(el) || el.offsetParent === null) return;
        const id = window.turnstile.render(el, {
          sitekey: cfg.turnstileSiteKey, theme: "light", size: "flexible",
          callback: t => captcha.tokens.set(el, t),
          "expired-callback": () => captcha.tokens.delete(el),
          "error-callback": () => captcha.tokens.delete(el)
        });
        captcha.widgets.set(el, id);
      });
    });
  }
  function captchaToken(form) {
    if (!captcha.enabled) return { ok: true, token: undefined };
    const el = $$("[data-captcha]", form).find(x => x.offsetParent !== null);
    const token = el && captcha.tokens.get(el);
    return token ? { ok: true, token, el } : { ok: false };
  }
  function resetCaptcha(form) {
    $$("[data-captcha]", form).forEach(el => {
      captcha.tokens.delete(el);
      if (window.turnstile && captcha.widgets.has(el)) window.turnstile.reset(captcha.widgets.get(el));
    });
  }
  function requireCaptcha(form) {
    const c = captchaToken(form);
    if (!c.ok) { alertBox("error", "Please complete the security check."); return null; }
    return c;
  }

  /* Tabs ------------------------------------------------------------------ */
  function bindTabs() {
    const tabs = $$('[role="tab"]');
    if (!tabs.length) return;
    function select(tab) {
      tabs.forEach(t => {
        const on = t === tab;
        t.setAttribute("aria-selected", String(on));
        t.tabIndex = on ? 0 : -1;
        document.getElementById(t.getAttribute("aria-controls")).hidden = !on;
      });
      alertBox();
      renderCaptchas(document.getElementById(tab.getAttribute("aria-controls")));
      try { sessionStorage.setItem("bv.authTab", tab.id); } catch (e) { /* ignore */ }
    }
    tabs.forEach((t, i) => {
      t.addEventListener("click", () => select(t));
      t.addEventListener("keydown", e => {
        if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
        const n = tabs[(i + (e.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length];
        n.focus(); select(n);
      });
    });
    let saved = null;
    try { saved = sessionStorage.getItem("bv.authTab"); } catch (e) { /* ignore */ }
    const initial = (params.get("method") === "phone" && $("#tab-phone")) || (saved && document.getElementById(saved)) || tabs[0];
    select(initial);
  }

  /* Common bindings -------------------------------------------------------- */
  function bindCommon() {
    $$("[data-pw-toggle]").forEach(b => b.addEventListener("click", () => {
      const input = document.getElementById(b.dataset.pwToggle);
      const show = input.type === "password";
      input.type = show ? "text" : "password";
      b.textContent = show ? "Hide" : "Show";
      b.setAttribute("aria-pressed", String(show));
      b.setAttribute("aria-label", show ? "Hide password" : "Show password");
    }));
    $$("[data-keep-next]").forEach(a => { if (params.get("next")) a.href += (a.href.indexOf("?") > -1 ? "&" : "?") + "next=" + encodeURIComponent(nextPage); });
    $$("[data-country]").forEach(fillCountries);
    // Clear a field's error as soon as the user edits it.
    $$(".auth-form .input").forEach(i => i.addEventListener("input", () => { if (i.getAttribute("aria-invalid") === "true") fieldError(i, ""); }));
    $$('.auth-form input[name="terms"]').forEach(c => c.addEventListener("change", () => { if (c.checked) termsError(c.closest("form"), ""); }));
    $$(".otp-input").forEach(i => i.addEventListener("input", () => { i.value = i.value.replace(/\D/g, "").slice(0, 6); }));
    $$('input[type="password"][autocomplete="new-password"]').forEach(i => { if ($("[data-pw-meter]", i.closest(".field"))) bindPasswordMeter(i); });
  }

  function notConfigured() {
    alertBox("info", "Sign-in is not connected yet. Add your Supabase settings to <code>.env</code> and rebuild the site — see <code>docs/AUTH-SUPABASE.md</code>. Meanwhile you can <a href=\"dashboard.html\">explore the dashboard demo</a>.");
    $$("form, [data-oauth]").forEach(el => {
      el.addEventListener("submit", e => { e.preventDefault(); e.stopImmediatePropagation(); notConfiguredAlert(); }, true);
      el.addEventListener("click", e => { if (el.matches("[data-oauth]")) { e.preventDefault(); e.stopImmediatePropagation(); notConfiguredAlert(); } }, true);
    });
  }
  function notConfiguredAlert() { alertBox("info", "Sign-in is not connected yet. See <code>docs/AUTH-SUPABASE.md</code> to connect Supabase. <a href=\"dashboard.html\">Open the dashboard demo</a>."); }

  /* Google ------------------------------------------------------------------ */
  function bindOAuth() {
    $$("[data-oauth]").forEach(b => b.addEventListener("click", async () => {
      alertBox();
      busy(b, true, "Redirecting to Google…");
      const { error } = await client.auth.signInWithOAuth({
        provider: b.dataset.oauth,
        options: { redirectTo: callbackUrl(), queryParams: { prompt: "select_account" } }
      });
      if (error) { busy(b, false); alertBox("error", friendly(error)); }
    }));
  }

  /* Email + password ------------------------------------------------------- */
  function bindEmailLogin(form) {
    form.addEventListener("submit", async e => {
      e.preventDefault(); alertBox();
      const email = form.email.value.trim(), password = form.password.value;
      const ok = fieldError(form.email, validEmail(email) ? "" : "Enter a valid email address.") &
                 fieldError(form.password, password ? "" : "Enter your password.");
      if (!ok) return;
      const c = requireCaptcha(form); if (!c) return;
      const btn = $('[type="submit"]', form); busy(btn, true, "Signing in…");
      const { error } = await client.auth.signInWithPassword({ email, password, options: { captchaToken: c.token } });
      resetCaptcha(form);
      if (error) {
        busy(btn, false);
        form.password.value = "";
        alertBox("error", friendly(error) + (error.code === "email_not_confirmed" ? ' <button type="button" class="auth-linkbtn" data-resend-link>Send the link again</button>' : ""));
        const r = $("[data-resend-link]");
        if (r) r.addEventListener("click", () => resendConfirmation(email));
        return;
      }
      goNext();
    });
  }

  async function resendConfirmation(email) {
    const { error } = await client.auth.resend({ type: "signup", email, options: { emailRedirectTo: callbackUrl() } });
    alertBox(error && error.status === 429 ? "error" : "success", error && error.status === 429 ? friendly(error) : "If that address needs confirming, a new link is on its way.");
  }

  function bindPhone(form, isSignup) {
    const stepPhone = $('[data-step="phone"]', form), stepCode = $('[data-step="code"]', form);
    const resendBtn = $("[data-resend]", form), countdown = $("[data-countdown]", form);
    let phone = null, timer = null, attempts = 0, name = "";

    function startCountdown() {
      let left = RESEND_SECONDS;
      resendBtn.disabled = true;
      clearInterval(timer);
      const tick = () => {
        countdown.textContent = left > 0 ? "in " + left + "s" : "";
        if (left-- <= 0) { clearInterval(timer); resendBtn.disabled = false; }
      };
      tick(); timer = setInterval(tick, 1000);
    }
    async function sendCode(btn) {
      const c = requireCaptcha(form); if (!c) return false;
      busy(btn, true, "Sending code…");
      const { error } = await client.auth.signInWithOtp({
        phone,
        options: { shouldCreateUser: isSignup, channel: "sms", captchaToken: c.token, data: isSignup ? { full_name: name } : undefined }
      });
      resetCaptcha(form); busy(btn, false);
      if (error) { alertBox("error", friendly(error)); return false; }
      return true;
    }
    function showCode() {
      stepPhone.hidden = true; stepCode.hidden = false;
      $("[data-phone-display]", form).textContent = maskPhone(phone);
      attempts = 0;
      startCountdown();
      const code = $(".otp-input", form); code.value = ""; code.focus();
      alertBox("success", "We've sent a 6-digit code by SMS. It expires in a few minutes.");
    }

    form.addEventListener("submit", async e => {
      e.preventDefault(); alertBox();
      if (!stepPhone.hidden) {
        const input = form.phone, country = $("[data-country]", form).value;
        phone = toE164(country, input.value);
        let ok = fieldError(input, phone ? "" : "Enter a valid " + COUNTRIES[country].name + " mobile number.");
        if (isSignup) {
          name = form.full_name.value.trim();
          ok = fieldError(form.full_name, name.length >= 2 ? "" : "Enter your full name.") & ok;
          ok = termsError(form, form.terms.checked ? "" : "Please accept the terms to continue.") & ok;
        }
        if (!ok) return;
        if (await sendCode($('[type="submit"]', stepPhone))) showCode();
        return;
      }
      const codeInput = form.code;
      const token = codeInput.value.trim();
      if (!fieldError(codeInput, /^\d{6}$/.test(token) ? "" : "Enter the 6-digit code.")) return;
      if (attempts >= MAX_CODE_ATTEMPTS) { alertBox("error", "Too many incorrect codes. Please request a new code."); return; }
      const btn = $('[type="submit"]', stepCode); busy(btn, true, "Verifying…");
      const { error } = await client.auth.verifyOtp({ phone, token, type: "sms" });
      busy(btn, false);
      if (error) {
        attempts++;
        codeInput.value = ""; codeInput.focus();
        alertBox("error", friendly(error) + (attempts >= MAX_CODE_ATTEMPTS ? " Please request a new code." : ""));
        return;
      }
      goNext();
    });
    resendBtn.addEventListener("click", async () => { alertBox(); if (await sendCode(resendBtn)) { attempts = 0; startCountdown(); alertBox("success", "A new code is on its way."); } });
    $("[data-change-phone]", form).addEventListener("click", () => {
      clearInterval(timer); stepCode.hidden = true; stepPhone.hidden = false; alertBox();
      renderCaptchas(form); form.phone.focus();
    });
  }

  /* Forgot / reset password ------------------------------------------------ */
  function bindForgot(form) {
    form.addEventListener("submit", async e => {
      e.preventDefault(); alertBox();
      const email = form.email.value.trim();
      if (!fieldError(form.email, validEmail(email) ? "" : "Enter a valid email address.")) return;
      const c = requireCaptcha(form); if (!c) return;
      const btn = $('[type="submit"]', form); busy(btn, true, "Sending…");
      const { error } = await client.auth.resetPasswordForEmail(email, { redirectTo: siteUrl + "/reset-password.html", captchaToken: c.token });
      resetCaptcha(form); busy(btn, false);
      if (error && error.status === 429) { alertBox("error", friendly(error)); return; }
      form.hidden = true;
      alertBox("success", "If an account exists for <strong>" + esc(email) + "</strong>, we've sent a link to reset your password. The link expires after a short time.");
    });
  }

  async function initReset() {
    const form = $('[data-form="reset"]'), intro = $("[data-reset-intro]");
    const fail = () => { intro.innerHTML = 'This reset link is invalid or has expired. <a href="forgot-password.html">Request a new link</a>.'; };
    const th = params.get("token_hash");
    if (th) {
      const { error } = await client.auth.verifyOtp({ token_hash: th, type: "recovery" });
      if (error) return fail();
      history.replaceState(null, "", location.pathname);
    } else {
      if (params.get("error_description") || hashParams.get("error_description")) return fail();
      const { data } = await client.auth.getSession();
      if (!data.session) return fail();
    }
    intro.textContent = "Choose a new password for your account.";
    form.hidden = false;
    form.password.focus();
    form.addEventListener("submit", async e => {
      e.preventDefault(); alertBox();
      const pw = form.password.value, confirm = form.confirm.value;
      const ok = fieldError(form.password, passwordProblem(pw)) & fieldError(form.confirm, pw === confirm ? "" : "The passwords don't match.");
      if (!ok) return;
      const btn = $('[type="submit"]', form); busy(btn, true, "Updating…");
      const { error } = await client.auth.updateUser({ password: pw });
      busy(btn, false);
      if (error) { alertBox("error", friendly(error)); return; }
      // Sign out other devices that may have been using the old password.
      await client.auth.signOut({ scope: "others" });
      form.hidden = true;
      intro.textContent = "";
      alertBox("success", 'Your password has been updated. <a href="dashboard.html">Continue to your dashboard</a>.');
    });
  }

  /* OAuth / email-link callback ------------------------------------------- */
  async function initCallback() {
    const msg = $("[data-callback-msg]"), retry = $("[data-callback-retry]");
    const fail = text => { $("h1").textContent = "We couldn't sign you in"; msg.textContent = text; retry.hidden = false; };
    const errDesc = params.get("error_description") || hashParams.get("error_description");
    if (errDesc) return fail(/expired/i.test(errDesc) ? "This link has expired. Please sign in or request a new link." : "The sign-in was cancelled or could not be completed. Please try again.");
    const th = params.get("token_hash"), type = params.get("type");
    if (th && ["signup", "email", "magiclink", "invite", "email_change"].indexOf(type) > -1) {
      const { error } = await client.auth.verifyOtp({ token_hash: th, type: type === "signup" ? "email" : type });
      if (error) return fail(friendly(error).replace(/<[^>]+>/g, ""));
    }
    // With PKCE, supabase-js exchanges ?code= for a session during initialisation.
    const { data } = await client.auth.getSession();
    if (data.session) { msg.textContent = "Signed in. Redirecting…"; goNext(); }
    else fail("This link is invalid or has already been used. Please sign in again.");
  }

  /* Dashboard guard -------------------------------------------------------- */
  function initials(user) {
    const n = (user.user_metadata && (user.user_metadata.full_name || user.user_metadata.name)) || user.email || user.phone || "?";
    const parts = String(n).replace(/@.*/, "").split(/[\s._-]+/).filter(Boolean);
    return ((parts[0] || "?")[0] + (parts[1] ? parts[1][0] : "")).toUpperCase();
  }
  async function guardDashboard() {
    const body = document.body;
    const status = $("[data-auth-status]");
    if (!configured) {
      body.classList.remove("auth-pending");
      if (status) status.textContent = "Sign-in is not connected (demo mode).";
      window.BalVoiceAuth = { mode: "demo", user: null, client: null, role: "admin" };
      document.dispatchEvent(new CustomEvent("balvoice:auth"));
      return;
    }
    const { data } = await client.auth.getSession();
    if (!data.session) { location.replace("login.html?next=" + encodeURIComponent(safeNext("dashboard.html" + location.hash))); return; }
    const user = data.session.user;
    const { data: staff, error: staffError } = await client.from("staff").select("role, active").eq("user_id", user.id).maybeSingle();
    if (staffError || !staff || !staff.active) {
      body.classList.remove("auth-pending");
      const view = $("#view");
      if (view) view.innerHTML = '<div class="box"><div class="empty"><h2>No dashboard access</h2><p>' +
        (staffError ? "We couldn't check your access. Please refresh the page." : "This account (" + esc(user.email || user.phone || "") + ") is not an active BalVoice staff account. Ask an administrator to invite you.") +
        '</p><button type="button" class="btn btn-secondary" id="noaccess-signout">Sign out</button></div></div>';
      const so = $("#noaccess-signout");
      if (so) so.addEventListener("click", async () => { await client.auth.signOut(); location.replace("login.html"); });
      window.BalVoiceAuth = { mode: "denied", user, client: null };
      document.dispatchEvent(new CustomEvent("balvoice:auth"));
      return;
    }
    window.BalVoiceAuth = { mode: "supabase", user, client, role: staff.role };
    body.classList.remove("auth-pending");
    const name = (user.user_metadata && (user.user_metadata.full_name || user.user_metadata.name)) || "";
    const ident = user.email || user.phone && ("+" + String(user.phone).replace(/^\+/, "")) || "";
    if (status) status.textContent = "Signed in as " + (name || ident) + ".";
    const avatar = $(".avatar");
    if (avatar) {
      const menu = document.createElement("div");
      menu.className = "user-menu";
      menu.innerHTML =
        '<button type="button" class="avatar avatar-btn" aria-haspopup="true" aria-expanded="false" aria-label="Account menu">' + esc(initials(user)) + "</button>" +
        '<div class="user-pop" hidden><p class="user-name">' + esc(name || "Your account") + '</p><p class="user-id">' + esc(ident) + "</p>" +
        '<button type="button" class="user-signout">Sign out</button></div>';
      avatar.replaceWith(menu);
      const btn = $(".avatar-btn", menu), pop = $(".user-pop", menu);
      const toggle = open => { pop.hidden = !open; btn.setAttribute("aria-expanded", String(open)); };
      btn.addEventListener("click", e => { e.stopPropagation(); toggle(pop.hidden); });
      document.addEventListener("click", e => { if (!menu.contains(e.target)) toggle(false); });
      document.addEventListener("keydown", e => { if (e.key === "Escape") toggle(false); });
      $(".user-signout", menu).addEventListener("click", async e => {
        e.currentTarget.disabled = true;
        await client.auth.signOut(); // the SIGNED_OUT listener below redirects
      });
    }
    document.dispatchEvent(new CustomEvent("balvoice:auth"));
    let leaving = false;
    client.auth.onAuthStateChange(event => {
      if (event === "SIGNED_OUT" && !leaving) { leaving = true; location.replace("login.html"); }
    });
  }

  /* Init ------------------------------------------------------------------- */
  async function init() {
    if (document.body.classList.contains("app-body")) { guardDashboard(); return; }
    const page = ($("[data-auth-page]") || {}).dataset ? $("[data-auth-page]").dataset.authPage : null;
    if (!page) return;
    bindCommon();
    bindTabs();
    renderCaptchas(document);
    if (!configured) { notConfigured(); return; }

    if (page === "login") {
      const { data } = await client.auth.getSession();
      if (data.session) { goNext(); return; }
      bindOAuth();
    }
    if (page === "login") { bindEmailLogin($('[data-form="email-login"]')); bindPhone($('[data-form="phone-login"]'), false); }

    if (page === "forgot") bindForgot($('[data-form="forgot"]'));
    if (page === "reset") initReset();
    if (page === "callback") initCallback();
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
